"""Research-only robust log-periodogram weight fit with amplitude nuisances, no truth input."""
import numpy as np


SETTINGS=dict(grid_points=129,refinement_iterations=32,minimum_shape_contrast=1e-4,
    minimum_frequency_count=512,minimum_radius=.125,maximum_radius=.5)


def geometry(size):
    if size<8 or size%2:raise ValueError('Even square size >=8 required')
    y,x=np.mgrid[:size,:size];x=x-x.mean();y=y-y.mean()
    basis=np.stack((np.ones_like(x,dtype=float)/size,x/np.linalg.norm(x),y/np.linalg.norm(y)))
    hann=np.hanning(size+1)[:-1];window=hann[:,None]*hann[None,:]
    fy=np.fft.fftfreq(size)[:,None];fx=np.fft.fftfreq(size)[None,:];radius=np.sqrt(fy*fy+fx*fx)
    mask=(radius>=SETTINGS['minimum_radius'])&(radius<=SETTINGS['maximum_radius'])&((fy>0)|((fy==0)&(fx>0)))
    return basis,window,mask


def expected_periodogram(spectrum):
    """Exact stationary periodic covariance expectation after plane projection + Hann window."""
    spectrum=np.asarray(spectrum,dtype=float)
    if spectrum.ndim!=2 or spectrum.shape[0]!=spectrum.shape[1] or not np.isfinite(spectrum).all():
        raise ValueError('Finite square marginal PSD required')
    if spectrum.min() < -1e-10*max(1.,float(spectrum.max())):raise ValueError('Negative PSD')
    spectrum=np.maximum(spectrum,0);n=len(spectrum);basis,window,_=geometry(n)
    power=np.fft.ifft2(np.fft.fft2(spectrum)*np.fft.fft2(abs(np.fft.fft2(window))**2)).real/(n*n)
    projected=np.array([np.fft.ifft2(spectrum*np.fft.fft2(u)).real for u in basis])
    g=np.fft.fft2(window[None]*basis,axes=(-2,-1))
    cross=np.fft.fft2(window[None]*projected,axes=(-2,-1))
    trend_covariance=np.einsum('iyx,jyx->ij',basis,projected)
    power-=2*np.sum((g.conj()*cross).real,axis=0)
    power+=np.einsum('iyx,jyx,ij->yx',g,g.conj(),trend_covariance).real
    return power/np.sum(window*window)


def template(covariance):
    c=np.asarray(covariance,dtype=float)
    if c.shape!=(3,3,128,128) or not np.isfinite(c).all():raise ValueError('Finite full128 covariance required')
    variance=np.diag(c[:,:,0,0])
    if np.min(variance)<=1e-24:raise ValueError('Positive marginal covariance required')
    return np.array([expected_periodogram(np.fft.fft2(c[a,a]/variance[a]).real) for a in range(3)])


def observed_periodogram(planes):
    planes=np.asarray(planes,dtype=float)
    if planes.shape!=(3,128,128) or not np.isfinite(planes).all():raise ValueError('Finite native three-axis128 field required')
    basis,window,_=geometry(128)
    coefficients=np.einsum('cyx,jyx->cj',planes,basis)
    residual=planes-np.einsum('cj,jyx->cyx',coefficients,basis)
    return abs(np.fft.fft2(residual*window,axes=(-2,-1)))**2/np.sum(window*window)


def fit_log_power(logpower,low,high):
    logpower,low,high=[np.asarray(v,dtype=float) for v in (logpower,low,high)]
    if logpower.ndim!=2 or logpower.shape[0]!=3 or low.shape!=logpower.shape or high.shape!=logpower.shape or not all(np.isfinite(v).all() for v in (logpower,low,high)) or min(low.min(),high.min())<=0:
        raise ValueError('Finite three-axis supported log-power and positive templates required')
    ratio=np.log(high/low);contrast=float(np.max(abs(ratio-np.median(ratio,axis=1,keepdims=True))))
    if contrast<SETTINGS['minimum_shape_contrast']:return dict(status='unidentifiable_spectral_shapes',weight=None)
    def objective(weights):
        weights=np.atleast_1d(weights)
        model=(1-weights[:,None,None])*low[None]+weights[:,None,None]*high[None]
        residual=logpower[None]-np.log(model)
        center=np.median(residual,axis=2,keepdims=True)
        return np.median(abs(residual-center),axis=2).sum(axis=1)
    grid=np.linspace(0,1,SETTINGS['grid_points']);values=objective(grid);best=int(np.argmin(values))
    left,right=grid[max(0,best-1)],grid[min(len(grid)-1,best+1)];golden=(np.sqrt(5)-1)/2
    for _ in range(SETTINGS['refinement_iterations']):
        x=right-golden*(right-left);y=left+golden*(right-left)
        if objective(x)[0]<objective(y)[0]:right=y
        else:left=x
    candidates=np.array([0.,1.,grid[best],(left+right)/2]);costs=objective(candidates)
    weight=float(candidates[int(np.argmin(costs))]);model=(1-weight)*low+weight*high
    sigma=np.sqrt(np.exp(np.median(logpower-np.log(model),axis=1))/np.log(2))
    return dict(status='estimated_not_confidence_calibrated',weight=weight,sigma=sigma.tolist(),
        robust_log_spectral_dispersion=float(np.min(costs)),endpoint_shape_contrast=contrast,
        frequency_count=logpower.shape[1],zero_clamped_frequency_count=0)


def estimate(planes,low,high):
    if np.min(np.std(planes,axis=(1,2)))<1e-12:return dict(status='unmeasurable_axis',weight=None)
    _,_,mask=geometry(128)
    support=mask & np.all((low>1e-10)&(high>1e-10)&np.isfinite(low)&np.isfinite(high),axis=0)
    count=int(support.sum())
    if count<SETTINGS['minimum_frequency_count']:return dict(status='insufficient_spectral_support',weight=None)
    power=observed_periodogram(planes)[:,support]
    result=fit_log_power(np.log(np.maximum(power,np.finfo(float).tiny)),low[:,support],high[:,support])
    result['zero_clamped_frequency_count']=int(np.sum(power<=0))
    return result

