"""Ablation: normalize covariance anchors BEFORE interpolation, predict shape only, no sigma."""
from datetime import datetime, timezone
import json
from pathlib import Path
import numpy as np
from study_noise_neighbourhoods import ROOT,sha256,git
from study_noise_signal_covariance_prediction import normalized,physical,errors


def shape_blend(low,high,weight):
    if not np.isfinite(weight) or not 0<=weight<=1:
        raise ValueError('Convex interpolation without extrapolation required')
    return (1-weight)*normalized(np.asarray(low))+weight*normalized(np.asarray(high))


def shape_errors(prediction,reference):
    measured=errors(prediction,reference)
    return {k:measured[k] for k in ('normalized_covariance_squared_error',
        'mean_abs_log_hh_factor_error','gaussian_hh_factor_ratio')}


def run():
    names=('prediction-covariance-luminance-bruit-v001-20261027T192134Z.json',
        'transport-psd-gaussien-filtre-spectral-bruit-v002-20261027T190615Z.json')
    paths=[ROOT/'docs/validation/raw'/n for n in names];hashes=[sha256(p) for p in paths]
    parent,spectral=[json.loads(p.read_text(encoding='utf-8')) for p in paths]
    anchors={a['id']:a for a in parent['anchors']};records=[];started=datetime.now(timezone.utc)
    for row in parent['records']:
        item={k:row[k] for k in ('dataset','iso','a','b','rect','status')}
        if row['status']!='predicted_held_capture':records.append(item);continue
        for key in ('lower','upper','nearest_id'):
            if set(anchors[row[key]]['raw_names'])&{row['a'],row['b']}:
                raise ValueError('Held capture leaked into parent prediction')
        target=next(r for r in spectral['records'] if r['dataset']==row['dataset'] and r['a']==row['a'] and r['rect']==row['rect'])
        truth=physical(target);low=np.asarray(anchors[row['lower']]['physical_covariance'])
        high=np.asarray(anchors[row['upper']]['physical_covariance']);w=row['upper_weight']
        reference=np.asarray(anchors['training_'+str(row['iso'])]['physical_covariance'])
        nearest=np.asarray(anchors[row['nearest_id']]['physical_covariance'])
        predictions=dict(fixed=reference,nearest=nearest,physical_interpolation=(1-w)*low+w*high,
            shape_only=shape_blend(low,high,w))
        measured={k:shape_errors(v,truth) for k,v in predictions.items()}
        for mode,old_mode in (('fixed','fixed'),('nearest','nearest'),('physical_interpolation','interpolated')):
            for metric in ('normalized_covariance_squared_error','mean_abs_log_hh_factor_error'):
                if abs(measured[mode][metric]-row['metrics'][old_mode][metric])>1e-14:
                    raise ValueError('Previous prediction controls do not replay exactly')
        item.update(lower=row['lower'],upper=row['upper'],upper_weight=w,nearest_id=row['nearest_id'],metrics=measured)
        records.append(item)
    summaries=[]
    for previous in parent['summaries']:
        rows=[r for r in records if r['dataset']==previous['dataset'] and r['a']==previous['a'] and r['status']=='predicted_held_capture']
        means={mode:{metric:float(np.mean([r['metrics'][mode][metric] for r in rows]))
            for metric in ('normalized_covariance_squared_error','mean_abs_log_hh_factor_error')}
            for mode in ('fixed','nearest','physical_interpolation','shape_only')} if rows else {}
        passed=bool(rows) and all(means['shape_only'][metric]<means['fixed'][metric]
            and means['shape_only'][metric]<=means['nearest'][metric]
            for metric in ('normalized_covariance_squared_error','mean_abs_log_hh_factor_error'))
        summary=dict(dataset=previous['dataset'],iso=previous['iso'],a=previous['a'],predicted_quadrants=len(rows),
            mean_metrics=means,screen_passed=passed if rows else None)
        summaries.append(summary)
        if rows:print('Shape-only fold',previous['dataset'],previous['iso'],'screen',passed,means,flush=True)
    tested=[r for r in summaries if r['predicted_quadrants']]
    verdict='shape_only_promising_requires_new_validation' if tested and all(r['screen_passed'] for r in tested) else 'shape_only_linear_light_interpolation_not_retained'
    if len(records)!=48 or [sha256(p) for p in paths]!=hashes:raise ValueError('Incomplete/changed shape-only study')
    now=datetime.now(timezone.utc)
    output=ROOT/'docs/validation/raw'/f'prediction-correlation-separee-bruit-v001-{now.strftime("%Y%m%dT%H%M%SZ")}.json'
    dependencies=('study_noise_signal_covariance_prediction.py','study_noise_haar_factor_transport.py')
    result=dict(schema_version=1,data_version=1,started_at_utc=started.isoformat(),completed_at_utc=now.isoformat(),
        verdict=verdict,records=records,summaries=summaries,tested_capture_folds=len(tested),
        criteria=parent['criteria'],numpy_version=np.__version__,commit=git('rev-parse','HEAD'),
        runner_sha256=sha256(Path(__file__)),runner_source=Path(__file__).read_text(encoding='utf-8'),
        parents=[dict(path=str(p),sha256=h) for p,h in zip(paths,hashes)],
        dependencies={n:dict(sha256=sha256(ROOT/'tests'/n),source=(ROOT/'tests'/n).read_text(encoding='utf-8')) for n in dependencies},
        rules='Singleablation: normalizeEACHanchor to unitmarginalvariance before samefrozenconvexweight blend. All14targets/4heldcapturefolds/34abstentions andbrackets fromparent retained. Fixed/nearest/physicalcontrols replayed to1e-14. PredictNOsigma,doNOTusetruesigmatochooseweights;Donlyevaluation. Sameperfoldshape+HHscreen vsfixed/nearest,no tuning.',
        limitations='Sequentialhypothesis onpreviouslyexploredfourcaptures,notindependentvalidation. CorrelationnowdecoupledfromamplitudebutstillonlylinearY;no completeblindestimator,denoising or perceptionclaim. No production,camerauniversalvalidation or export.')
    with output.open('x',encoding='utf-8') as handle:json.dump(result,handle,ensure_ascii=False,indent=1,allow_nan=False)
    print('VERDICT',verdict,output,flush=True)


if __name__=='__main__':run()
